async function prepareRepayment(rid){const a=financeState.selected;if(!a)return;const get=id=>Number(document.getElementById('v356r_'+rid+'_'+id)?.value||0);const liability=get('liability'),interest=get('interest'),fee=get('fee');if(!liability)return alert(tr('Select a financing liability account.'));if(!await confirmAction({title:tr('Repayment accounting'),message:tr('No second bank movement will be generated.'),confirmLabel:tr('Prepare posting proposal'),details:[{label:'Finance payment ID',value:'#'+(a.repayments.find(x=>x.id===rid)?.finance_entry_id||'')},{label:'Loan liability account',value:String(liability)},{label:'Interest expense account',value:String(interest)},{label:'Fee expense account',value:String(fee)}]}))return;
const btn=document.getElementById('v356r_'+rid+'_submit');if(btn)btn.disabled=true;try{const out=await api('/api/accounting/financing-v356/'+a.id+'/repayment/'+rid+'/prepare-reclassification',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({liability_account_id:liability,interest_account_id:interest,fee_account_id:fee})});alert(out.message);await financingDetail(a.id)}catch(e){alert(e.message);if(btn)btn.disabled=false}}
async function matchFunding(id){const input=document.getElementById('v356fund_finance_id');const financeId=Number(input?.value);if(!Number.isSafeInteger(financeId)||financeId<=0)return alert(tr('Enter an existing Finance receipt ID.'));if(!await confirmAction({title:tr('Loan funding & liability'),message:tr('Only an existing verified receipt is linked. No cash or GL movement is created.'),confirmLabel:tr('Link funding receipt'),details:[{label:'Finance receipt ID',value:'#'+financeId}]}))return;const btn=document.getElementById('v356fund_match');if(btn)btn.disabled=true;try{const out=await api('/api/accounting/financing-v356/'+id+'/match-funding',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({finance_entry_id:financeId})});alert(out.message);await financingDetail(id)}catch(err){alert(err.message);if(btn)btn.disabled=false}}
async function prepareFunding(id){const liability=Number(document.getElementById('v356fund_liability')?.value);if(!liability)return alert(tr('Select a financing liability account.'));if(!await confirmAction({title:tr('Loan funding & liability'),message:tr('Reclassification of an already-posted receipt; no second bank movement.'),confirmLabel:tr('Prepare posting proposal'),details:[{label:'Liability account ID',value:String(liability)}]}))return;const btn=document.getElementById('v356fund_prepare');if(btn)btn.disabled=true;try{const out=await api('/api/accounting/financing-v356/'+id+'/prepare-funding-reclassification',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({liability_account_id:liability})});alert(out.message);await financingDetail(id)}catch(err){alert(err.message);if(btn)btn.disabled=false}}
async function printFinancing(id){const w=window.open('','_blank');if(!w)return alert(tr('Allow pop-ups to print the financing statement.'));w.document.write('<p>Preparing financing statement…</p>');try{const d=await api('/api/accounting/financing-v356/'+Number(id)+'/statement');const safe=h;const money=x=>Number(x||0).toLocaleString('en-US',{maximumFractionDigits:2});const rows=(d.repayments||[]).map(x=>`<tr><td>${safe(x.transaction_date)}</td><td>#${Number(x.finance_entry_id)}</td><td>${money(x.principal_krw)}</td><td>${money(x.interest_krw)}</td><td>${money(x.fee_krw)}</td><td>${safe(x.journal?.status||'Not prepared')}</td></tr>`).join('');const amendments=(d.amendments||[]).map(x=>`<tr><td>${x.effective_installment}</td><td>${safe(x.lender_reference)}</td><td>${money(x.revised_principal_krw)}</td><td>${x.remaining_months}</td><td>${x.annual_rate}%</td></tr>`).join('');const page=`<!doctype html><html><head><meta charset="utf-8"><title>Financing ${safe(d.agreement.agreement_no)}</title><style>body{font:13px Arial,sans-serif;margin:32px;color:#172536}h1{font-size:23px}h2{font-size:17px;margin-top:28px}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}th{background:#edf2f6}.note{border:1px solid #ddd;padding:12px;margin-top:20px;color:#555}@media print{button{display:none}}</style></head><body><h1>Blue Ocean Market — Financing Statement</h1><p>${safe(d.agreement.lender)} · ${safe(d.agreement.agreement_no)} · ${safe(d.agreement.currency)}</p><p>Agreement: ${safe(d.agreement.agreement_reference)}</p><table><tr><th>Opening principal</th><th>Verified principal paid</th><th>Outstanding principal</th></tr><tr><td>${money(d.agreement.opening_principal_krw)}</td><td>${money(d.totals.principal_krw)}</td><td>${money(d.outstanding_principal_krw)}</td></tr></table><h2>Verified repayment allocations</h2><table><tr><th>Date</th><th>Finance ID</th><th>Principal</th><th>Interest</th><th>Fees</th><th>GL adjustment</th></tr>${rows}</table><h2>Lender-authorized schedule changes</h2><table><tr><th>Effective #</th><th>Reference</th><th>Revised principal</th><th>Remaining months</th><th>Rate</th></tr>${amendments}</table><h2>Estimated future schedule</h2><table><tr><th>#</th><th>Due date</th><th>Principal</th><th>Interest</th><th>Remaining due</th></tr>${(d.estimate||[]).map(x=>`<tr><td>${x.number}</td><td>${safe(x.due_date)}</td><td>${money(x.principal_krw)}</td><td>${money(x.interest_krw)}</td><td>${money(x.remaining_due_krw)}</td></tr>`).join('')}</table><div class="note">${safe(d.basis)} Lease asset/liability recognition and historical GL reconciliation require authorized Accounting review. This document is not a lender-issued balance confirmation.</div><button onclick="print()">Print / Save PDF</button></body></html>`;w.document.open();w.document.write(page);w.document.close()}catch(e){w.document.body.textContent='Statement unavailable: '+e.message}}
function csvCell(value){let v=String(value??'');if(/^\s*[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
async function exportFinancing(id){try{const data=await api('/api/accounting/financing-v356/'+id+'/statement');const rows=[['Blue Ocean Market - financing operational statement'],['Agreement',data.agreement.agreement_no],['Lender',data.agreement.lender],['Currency',data.agreement.currency],['Opening principal',data.agreement.opening_principal_krw],['Outstanding principal',data.outstanding_principal_krw],['Basis',data.basis],[],['Repayment Finance ID','Date','Principal KRW','Interest KRW','Fees KRW','Finance status','Reclassification journal','Posting status']];for(const x of data.repayments)rows.push([x.finance_entry_id,x.transaction_date,x.principal_krw,x.interest_krw,x.fee_krw,x.verification_status,x.journal?.journal_no||'',x.journal?.status||'Not prepared']);rows.push([],['Estimated installment','Due date','Principal KRW','Interest KRW','Total KRW','Remaining KRW']);for(const x of data.estimate)rows.push([x.number,x.due_date,x.principal_krw,x.interest_krw,x.total_krw,x.remaining_principal_krw]);const content='\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='financing-'+String(data.agreement.agreement_no).replace(/[^a-zA-Z0-9_-]/g,'_')+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(href)}catch(err){alert(err.message)}}
window.v356PrintFinancing=printFinancing;window.v356MatchFunding=matchFunding;window.v356PrepareFunding=prepareFunding;window.v356ExportFinancing=exportFinancing;
window.v356PrepareRepayment=prepareRepayment;
