async function downloadFinancingPDF(id){try{const headers={Authorization:'Bearer '+token,'X-Language':currentLanguage==='ko'?'ko':'en'};if(selectedUnitId)headers['X-Business-Unit-ID']=selectedUnitId;else if(me?.business_unit_id)headers['X-Business-Unit-ID']=me.business_unit_id;const r=await fetch('/api/accounting/financing-v356/'+Number(id)+'/statement.pdf?lang='+(currentLanguage==='ko'?'ko':'en'),{headers});if(!r.ok){let e={};try{e=await r.json()}catch(_){}throw Error(e.error||'Statement PDF unavailable')}const blob=await r.blob();if(blob.type!=='application/pdf'&&blob.size<500)throw Error('PDF response is invalid');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='financing-'+Number(id)+'-'+(currentLanguage==='ko'?'ko':'en')+'.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){alert(e.message)}}
async function financingAudit(id){try{const data=await api('/api/accounting/financing-v356/'+Number(id)+'/financial-audit');const money=x=>k(x),lines=[data.agreement_no,'Operational principal: '+money(data.operational_principal_krw),'Source-linked posted liability: '+money(data.linked_posted_liability_krw),'Difference: '+money(data.linked_difference_krw),'Whole posted liability account: '+(data.full_posted_account_balance_krw===null?'Not linked':money(data.full_posted_account_balance_krw)),'Other postings on liability account: '+data.other_posted_journals.length,'Source-linked reconciled: '+(data.source_linked_reconciled?'Yes':'No'),'Review status: '+(data.accountant_review?.current?'Accountant-reviewed (current)':data.accountant_review?.stale?'Previous review stale — ledger changed':'Not yet reviewed'),'This is not a lender-certified statement.'];if(data.other_posted_journals.length)lines.push(...data.other_posted_journals.slice(0,15).map(x=>x.journal_no+' · '+x.source_type+' · '+money(x.delta_krw)));alert(lines.join('\n'))}catch(e){alert(e.message)}}
async function reviewFinancingReconciliation(id){try{const data=await api('/api/accounting/financing-v356/'+Number(id)+'/financial-audit');if(data.requires_review||!data.source_linked_reconciled)return alert(tr('Resolve missing, unposted or unrelated liability journals before approving reconciliation.'));if(data.accountant_review?.current)return alert(tr('This ledger snapshot is already reviewed.'));const statementDate=prompt(tr('Lender statement date (YYYY-MM-DD):'),new Date().toISOString().slice(0,10));if(!statementDate)return;const lenderReference=prompt(tr('Actual lender statement reference:'));if(!lenderReference)return;const notes=prompt(tr('Accountant reconciliation notes (at least 8 characters):'));if(!notes)return;const amount=data.operational_principal_krw;if(!await confirmAction({title:tr('Review financing reconciliation'),message:tr('Confirm lender evidence and matching posted liability. This records a review, not a lender certification or a new journal.'),confirmLabel:tr('Record review'),details:[{label:'Agreement',value:data.agreement_no},{label:'Balance (KRW)',value:k(amount)},{label:'Lender reference',value:lenderReference}]}))return;const out=await api('/api/accounting/financing-v356/'+Number(id)+'/review-reconciliation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reviewed_balance_krw:amount,statement_date:statementDate,lender_reference:lenderReference,notes})});alert(out.ok?tr('Reconciliation review recorded. A subsequent ledger change will make it stale.'):tr('Review could not be recorded.'))}catch(e){alert(e.message)}}
